// RH specific constants
#define RH_ENCODER_RESOLUTION 16384  // 14-bit
#define RH_MAX_VELOCITY_RPM 1500
#define RH_MAX_TORQUE_NM 4.0
#define RH_REDUCTION_RATIO 100
#define RH_BACKLASH_DEGREES 0.02f

// Internal state
static struct {
    bool initialized = false;
    bool enabled = false;
    bool fault = false;
    uint16_t status_word = 0;
    float target_position = 0.0f;
    float target_velocity = 0.0f;
    float target_torque = 0.0f;
    float actual_position = 0.0f;
    float actual_velocity = 0.0f;
    float actual_torque = 0.0f;
    float temperature = 25.0f;
    uint32_t current_mA = 0;
    ControlMode control_mode = CONTROL_POSITION;
    uint8_t motor_id = 0;
    ProtocolType protocol = PROTOCOL_CAN;
    float backlash_degrees = RH_BACKLASH_DEGREES;
} state;

RHDriver::RHDriver(uint8_t motorId, const MotorConfig& config)
    : _motorId(motorId), _config(config), _status(MOTOR_STATUS_IDLE),
      _temperature(0), _position(0), _velocity(0), _current(0),
      _backlashDegrees(RH_BACKLASH_DEGREES) {}

bool RHDriver::init() {
    // Initialize encoder
    pinMode(PIN_ENCODER_A, INPUT_PULLUP);
    pinMode(PIN_ENCODER_B, INPUT_PULLUP);
    pinMode(PIN_ENCODER_Z, INPUT_PULLUP);

    // Initialize motor PWM outputs
    pinMode(PIN_MOTOR_PWM_A, OUTPUT);
    pinMode(PIN_MOTOR_PWM_B, OUTPUT);
    analogWrite(PIN_MOTOR_PWM_A, 0);
    analogWrite(PIN_MOTOR_PWM_B, 0);

    // Initialize current sense
    pinMode(PIN_CURRENT_SENSE, INPUT);

    // Initialize temperature sense
    pinMode(PIN_TEMP_SENSE, INPUT);

    // Initialize communication protocol
    // TODO: Initialize CAN/RS485/EtherCAT based on protocol

    // Initialize status word
    state.status_word = (1 << 0) | (1 << 1);  // Ready | Enabled

    state.initialized = true;
    state.enabled = true;

    return true;
}

void RHDriver::deinit() {
    // Disable motor
    analogWrite(PIN_MOTOR_PWM_A, 0);
    analogWrite(PIN_MOTOR_PWM_B, 0);

    state.enabled = false;
    state.initialized = false;
}

MotorStatus RHDriver::getStatus() {
    if (!state.initialized) return MOTOR_STATUS_IDLE;
    if (state.fault) return MOTOR_STATUS_FAULT;
    if (state.enabled) return MOTOR_STATUS_RUNNING;
    return MOTOR_STATUS_IDLE;
}

float RHDriver::getTemperature() {
    // Read temperature sensor
    // TODO: Implement NTC thermistor reading
    return state.temperature;
}

int32_t RHDriver::getPosition() {
    // Read encoder position
    // TODO: Implement encoder reading
    return state.actual_position;
}

float RHDriver::getVelocity() {
    return state.actual_velocity;
}

float RHDriver::getCurrent() {
    // Read current sensor
    // TODO: Implement current sensing
    return state.actual_torque;
}

void RHDriver::setPosition(float target) {
    state.target_position = target;
    state.control_mode = CONTROL_POSITION;
}

void RHDriver::setVelocity(float target) {
    state.target_velocity = target;
    state.control_mode = CONTROL_VELOCITY;
}

void RHDriver::setTorque(float target) {
    state.target_torque = target;
    state.control_mode = CONTROL_TORQUE;
}

void RHDriver::enable() {
    state.enabled = true;
    state.status_word |= (1 << 1);  // Set Enabled bit
}

void RHDriver::disable() {
    state.enabled = false;
    state.status_word &= ~(1 << 1);  // Clear Enabled bit
    analogWrite(PIN_MOTOR_PWM_A, 0);
    analogWrite(PIN_MOTOR_PWM_B, 0);
}

void RHDriver::faultReset() {
